using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CharacterRelationsTests
{
    static readonly EntityId Player=new("created:test"),Other=new("created:other");
    static WorldSession Start(ulong seed=42,bool on=true,bool retainer=false){var a=NewGameWorldTests.Officer();var b=NewGameWorldTests.Officer(Other.Value,retainer?StartTemplate.Retainer:StartTemplate.Ronin,lord:retainer?Player.Value:null);var setup=NewGameWorldTests.Setup([a,b]);return new(NewGameWorld.Create(setup.World,setup.Registered,a.Id,seed,inspectionPolicy:LocalInspectionFindings.Policy,workPolicy:WorkFollowup.Policy,companionPolicy:PersonalCompanions.Policy,developmentPolicy:CharacterDevelopment.Policy,socialPolicy:on?CharacterRelations.Policy:null));}
    static void At(WorldSession s,long at)=>NewGameWorldTests.At(s,at);
    static readonly Lazy<ulong> Yes=new(()=>Find(true)),No=new(()=>Find(false));
    static ulong Find(bool value){for(ulong n=1;n<=100;n++){var s=Start(n);if(CharacterRelations.AcceptsCompanion(s.DiagnosticSnapshot(),Other,20,0,s.Revision+1)==value)return n;}throw new Exception("No stable profile for branch");}
    static CommandResult Act(WorldSession s,CompanionAction a,long amount=0,string? id=null)=>s.ManageCompanion(new(new(id??"request:social/"+s.Revision),Other,a,amount),s.PlayerControl,s.Revision);
    static WorldSession Agreed(){var s=Start(Yes.Value);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);return s;}
    [Fact]public void SixTraitsAreStableAndDoNotReroll(){var s=Start();var w=s.DiagnosticSnapshot();var before=Enum.GetValues<SocialTrait>().Select(t=>CharacterRelations.DiagnosticTrait(w,Other,t)).ToArray();At(s,100);Assert.Equal(before,Enum.GetValues<SocialTrait>().Select(t=>CharacterRelations.DiagnosticTrait(s.DiagnosticSnapshot(),Other,t)).ToArray());Assert.Equal(6,before.Length);Assert.All(before,n=>Assert.InRange(n,10,90));}
    [Fact]public void OldConsentAndSerializationRemainOptOut(){var s=Start(No.Value,false);Assert.Null(s.DiagnosticSnapshot().Social);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20).Code);Assert.DoesNotContain("SocialPolicy",System.Text.Encoding.UTF8.GetString(ContractJson.Write(s.DiagnosticSnapshot())));}
    [Fact]public void StableRefusalDoesNotSpendMoneyOrCommit(){var s=Start(No.Value);var before=ContractJson.Write(s.DiagnosticSnapshot());for(int n=0;n<3;n++)Assert.Equal(ResultCode.NotAvailable,Act(s,CompanionAction.Agree,20,"request:refusal/"+n).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void LocalPaymentCreatesOnlyRecipientToPayerReaction(){var s=Agreed();var w=s.DiagnosticSnapshot();Assert.Equal(5,CharacterRelations.DiagnosticScores(w,Other,Player).Trust);Assert.Equal(0,CharacterRelations.DiagnosticScores(w,Player,Other).Trust);Assert.Equal(0,CharacterRelations.DiagnosticScores(w,new("person:nobunaga"),Player).Trust);Assert.Equal(980,NewGameWork.Balance(w,Player));Assert.Equal(1020,NewGameWork.Balance(w,Other));Assert.Empty(CharacterRelations.View(w,Other)!.Known);}
    [Fact]public void RetryCannotPayOrReactTwice(){var s=Start(Yes.Value);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Agree,20,"request:once").Code);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,Act(s,CompanionAction.Agree,20,"request:once").Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    static WorldSession Completed(bool opened){var s=Agreed();Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Inspect).Code);At(s,8);if(opened){var m=s.DiagnosticSnapshot().Companions!.Reports.Single().Message;Assert.Equal(ResultCode.Accepted,s.Open(Player,new(m),s.Revision).Code);}return s;}
    [Fact]public void UnopenedReportDoesNotUpdateRecipient(){var s=Completed(false);var w=s.DiagnosticSnapshot();Assert.Equal(0,CharacterRelations.DiagnosticScores(w,Player,Other).Trust);Assert.Empty(CharacterRelations.View(w,Other)!.Known);}
    [Fact]public void OpeningActualReportCreatesDatedDirectedReactionOnce(){var s=Completed(true);var w=s.DiagnosticSnapshot();Assert.Equal(4,CharacterRelations.DiagnosticScores(w,Player,Other).Trust);Assert.Equal(5,CharacterRelations.DiagnosticScores(w,Other,Player).Trust);var card=Assert.Single(CharacterRelations.View(w,Other)!.Known);Assert.True(card.ObservedAt<=card.LearnedAt);var m=w.Companions!.Reports.Single().Message;var before=ContractJson.Write(w);Assert.Equal(ResultCode.AlreadyAccepted,s.Open(Player,new(m),s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PublicViewDoesNotExposeUnobservedTraitChanges(){var a=Start(Yes.Value);var b=Start(No.Value);Assert.Equal(ContractJson.Write(CharacterRelations.View(a.DiagnosticSnapshot(),Other)),ContractJson.Write(CharacterRelations.View(b.DiagnosticSnapshot(),Other)));}
    [Fact]public void PersonHouseAndOrganizationLoyaltiesAreSeparate(){var s=Start(retainer:true);var w=s.DiagnosticSnapshot();Assert.True(CharacterRelations.DiagnosticLoyalty(w,Other,LoyaltyTarget.Person,Player,0,1)>0);Assert.Equal(0,CharacterRelations.DiagnosticLoyalty(w,Other,LoyaltyTarget.House,Player,0,1));Assert.Equal(0,CharacterRelations.DiagnosticLoyalty(w,Other,LoyaltyTarget.Organization,Player,0,1));}
    [Fact]public void LaterPaymentsDoNotRewriteOldAcceptance(){var s=Agreed();At(s,86401);Assert.Equal(ResultCode.Accepted,Act(s,CompanionAction.Pay,20).Code);new WorldSession(s.DiagnosticSnapshot());Assert.Equal(10,CharacterRelations.DiagnosticScores(s.DiagnosticSnapshot(),Other,Player).Trust);}
    [Fact]public void ForgedTrustWithoutSourceIsRejected(){var s=Agreed();var w=s.DiagnosticSnapshot();w.Social!.Reactions[0]=w.Social.Reactions[0] with{Trust=99};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void OmittingKnownReactionIsRejected(){var s=Completed(true);var w=s.DiagnosticSnapshot();w.Social=w.Social! with{Reactions=[]};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)]public void ActualGenerationRecoveryPreservesSocialAndFuture(int phase){var s=phase==0?Start(Yes.Value):phase==1?Agreed():Completed(phase==3);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"social-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"social",w.WorldId).Published);var host=new WorldSessionHost(Start(Yes.Value));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("social"),host.Current,host.Current.Revision));Assert.Equal(ContractJson.Write(w),ContractJson.Write(host.Current.DiagnosticSnapshot()));Assert.Equal(ContractJson.Write(CharacterRelations.View(w,Other)),ContractJson.Write(CharacterRelations.View(host.Current.DiagnosticSnapshot(),Other)));var dir=Environment.GetEnvironmentVariable("HAKUTAI_WORLD_CLASH_QA_DIR");if(!string.IsNullOrEmpty(dir)){File.WriteAllBytes(Path.Combine(dir,"character-relations-"+phase+".before.json"),ContractJson.Write(w));File.WriteAllBytes(Path.Combine(dir,"character-relations-"+phase+".restored.json"),ContractJson.Write(host.Current.DiagnosticSnapshot()));}foreach(var x in new[]{s,host.Current})At(x,x.Seconds+10);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}

    [Fact]public void KnownPersonalDutyCanChangeTheSameVoluntaryOffer(){ulong chosen=0;for(ulong n=1;n<=100;n++){var free=Start(n);var bound=Start(n,retainer:true);if(!CharacterRelations.AcceptsCompanion(free.DiagnosticSnapshot(),Other,20,0,1)&&CharacterRelations.AcceptsCompanion(bound.DiagnosticSnapshot(),Other,20,0,1)){chosen=n;break;}}Assert.True(chosen>0);var no=Start(chosen);var yes=Start(chosen,retainer:true);Assert.Equal(ResultCode.NotAvailable,Act(no,CompanionAction.Agree,20).Code);Assert.Equal(ResultCode.Accepted,Act(yes,CompanionAction.Agree,20).Code);}
    [Fact]public void RelationCannotPrecedeActualKnowledge(){var s=Completed(true);var w=s.DiagnosticSnapshot();var n=Array.FindIndex(w.Social!.Reactions,r=>r.Kind=="known-completion");w.Social.Reactions[n]=w.Social.Reactions[n] with{LearnedAt=0};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
    [Fact]public void UnknownThirdPartyKnowledgeCannotBeInvented(){var s=Completed(true);var w=s.DiagnosticSnapshot();var n=Array.FindIndex(w.Social!.Reactions,r=>r.Kind=="known-completion");w.Social.Reactions[n]=w.Social.Reactions[n] with{Observer=new("person:nobunaga")};Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}
}
